targets.expr:
topk(1,
  pmm_ha_raft_term
  and on(node_id) (
    (pmm_ha_leader_status == 1)
    and on(node_id)
    label_replace(
      kube_pod_info{
        exported_namespace="$namespace",
        exported_pod=~"${release}-${pmm_suffix_regex}"
      },
      "node_id", "$1", "exported_pod", "(.*)"
    )
  )
)
or (
  label_replace(vector(0), "node_id", "No active instance", "", "")
  unless on() (
    max(
      (pmm_ha_leader_status == 1)
      and on(node_id)
      label_replace(
        kube_pod_info{
          exported_namespace="$namespace",
          exported_pod=~"${release}-${pmm_suffix_regex}"
        },
        "node_id", "$1", "exported_pod", "(.*)"
      )
    ) == 1
  )
)

(
  max by(name) (
    (patroni_primary == 1)
    and on(name)
    label_replace(
      kube_pod_info{
        exported_namespace="$namespace",
        exported_pod=~"${release}-pg-db-.*",
        exported_pod!~".*(${pg_exclude_regex}).*"
      },
      "name", "$1", "exported_pod", "(.*)"
    )
  )
)
or (
  label_replace(vector(0), "name", "No active instance", "", "")
  unless on() (
    max(
      (patroni_primary == 1)
      and on(name)
      label_replace(
        kube_pod_info{
          exported_namespace="$namespace",
          exported_pod=~"${release}-pg-db-.*",
          exported_pod!~".*(${pg_exclude_regex}).*"
        },
        "name", "$1", "exported_pod", "(.*)"
      )
    ) == 1
  )
)

label_replace(
  max by(node_id) (
    pmm_ha_leader_status
    and on(node_id)
    label_replace(
      kube_pod_info{
        exported_namespace="$namespace",
        exported_pod=~"${release}-${pmm_suffix_regex}"
      },
      "node_id", "$1", "exported_pod", "(.*)"
    )
  ),
  "exported_pod", "$1", "node_id", "(.*)"
)

max by(exported_pod) (
  (
    (
      label_replace(max by(name) (patroni_primary), "exported_pod", "$1", "name", "(.*)")
      or
      label_replace(
        max by(node_name) (1 - clamp_max(pg_replication_is_replica, 1)),
        "exported_pod", "$1", "node_name", ".*(${release}-pg-db-[a-zA-Z0-9-]+)"
      )
    )
    and on(exported_pod)
    max by(exported_pod) (
      kube_pod_info{
      exported_namespace="$namespace",
      exported_pod=~"${release}-pg-db-.*",
      exported_pod!~".*(${pg_exclude_regex}).*"
    }
    )
  )
  or
  (max by(exported_pod) (
    kube_pod_info{
      exported_namespace="$namespace",
      exported_pod=~"${release}-pg-db-.*",
      exported_pod!~".*(${pg_exclude_regex}).*"
    }
  ) * 0 - 1)
)

max by(exported_pod) (
  (
    (
      label_replace(
        max by(name) (patroni_postgres_streaming) + on(name) max by(name) (patroni_primary),
        "exported_pod", "$1", "name", "(.*)"
      )
      or
      label_replace(
        max by(node_name) (
          (1 - clamp_max(pg_replication_is_replica, 1))
          +
          (clamp_max(pg_replication_is_replica, 1) * (pg_replication_lag_seconds < bool 60))
        ),
        "exported_pod", "$1", "node_name", ".*(${release}-pg-db-[a-zA-Z0-9-]+)"
      )
    )
    and on(exported_pod)
    max by(exported_pod) (
      kube_pod_info{
      exported_namespace="$namespace",
      exported_pod=~"${release}-pg-db-.*",
      exported_pod!~".*(${pg_exclude_regex}).*"
    }
    )
  )
  or
  (max by(exported_pod) (
    kube_pod_info{
      exported_namespace="$namespace",
      exported_pod=~"${release}-pg-db-.*",
      exported_pod!~".*(${pg_exclude_regex}).*"
    }
  ) * 0 - 1)
)

max by(exported_pod) (
  (
    label_replace(max by(instance) (ClickHouseAsyncMetrics_KeeperIsLeader), "pod_ip", "$1", "instance", "([0-9.]+):.*")
    * on(pod_ip) group_left(exported_pod)
    max by(pod_ip, exported_pod) (kube_pod_info{exported_namespace="$namespace", exported_pod=~"${release}-${clickhouse_suffix_regex}"})
  )
  or
  (
    min by(exported_pod) (
      (kube_pod_container_status_ready{exported_namespace="$namespace", exported_pod=~"${release}-pmmdb.*"} == 1) * 2
    )
  )
)

max by(service, proxy, server) (
  haproxy_server_status{
    namespace="$namespace",
    service=~"${release}-.*"
  }
)
